"""Synthetic invoice record, not a fiscal invoice integration."""
def create(repo, order_id, amount_cents):
    if repo.find("invoices", lambda row: row["order_id"] == order_id):
        raise ValueError("invoice exists")
    return repo.insert("invoices", {"order_id": order_id, "amount_cents": amount_cents, "status": "issued"})

def void(repo, order_id):
    rows = repo.find("invoices", lambda row: row["order_id"] == order_id)
    if not rows:
        raise ValueError("invoice missing")
    rows[0]["status"] = "void"

"""Synthetic delivery-triggered points posting, amount measured in cents."""
def prepare(repo, order_id, resident_id, amount_cents):
    return repo.insert("loyalty", {"order_id": order_id, "resident_id": resident_id, "points": amount_cents // 100, "status": "pending"})

def grant(repo, order_id):
    order = repo.get("orders", order_id)
    rows = repo.find("loyalty", lambda row: row["order_id"] == order_id and row["status"] == "pending")
    if order["status"] != "delivered" or not rows:
        raise ValueError("points posting rejected")
    row = rows[0]
    resident = repo.get("residents", row["resident_id"])
    resident["points"] += row["points"]
    row["status"] = "posted"

"""Synthetic local refund ledger; caller controls transaction."""
def issue(repo, order_id, amount_cents):
    order = repo.get("orders", order_id)
    approved = repo.find("returns", lambda row: row["order_id"] == order_id and row["status"] == "approved")
    if order is None or (order["status"] != "cancelled" and not approved):
        raise ValueError("refund not allowed")
    payments = repo.find("payments", lambda row: row["order_id"] == order_id)
    if not payments or type(amount_cents) is not int or amount_cents <= 0:
        raise ValueError("payment or amount invalid")
    payment = payments[0]
    if amount_cents > payment["amount_cents"] - payment["refunded_cents"]:
        raise ValueError("refund exceeds captured balance")
    payment["refunded_cents"] += amount_cents
    if payment["refunded_cents"] == payment["amount_cents"]:
        order["payment_state"] = "refunded"
    return repo.insert("refunds", {"order_id": order_id, "amount_cents": amount_cents})

"""Synthetic pending notification queue with a bounded attempt count."""
from modules.notifications.service import send

def enqueue(repo, kind, order_id):
    return repo.insert("outbox", {"kind": kind, "order_id": order_id, "status": "pending", "attempts": 0})

def deliver_pending(repo, limit, max_attempts, transport):
    eligible = repo.find("outbox", lambda row: row["status"] == "pending" and row["attempts"] < max_attempts)
    selected = sorted(eligible, key=lambda row: row["id"])[:limit]
    for event in selected:
        try:
            send(event, transport)
        except OSError:
            event["attempts"] += 1
        else:
            event["attempts"] += 1
            event["status"] = "sent"
    return len(selected)

"""Synthetic formatter; a caller-supplied transport is required."""
TEMPLATES = {"order_created": "订单已创建", "order_cancelled": "订单已取消", "order_shipped": "订单已出库"}

def send(event, transport):
    if transport is None:
        raise OSError("transport unavailable")
    transport.send({"order_id": event["order_id"], "message": TEMPLATES[event["kind"]]})
